import React from 'react';

interface NavbarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  cartCount: number;
  openCart: () => void;
}

export const Navbar: React.FC<NavbarProps> = ({ activeTab, setActiveTab, cartCount, openCart }) => {
  return (
    <header className="navbar">
      <div className="container navbar-inner">
        <div className="brand-logo" onClick={() => setActiveTab('home')}>
          <span>✦</span>
          <span>ApexStore — Modern Commerce</span>
        </div>
        <nav>
          <ul className="nav-links">
            <li>
              <button
                className={`nav-link ${activeTab === 'home' ? 'active' : ''}`}
                onClick={() => setActiveTab('home')}
              >
                Home
              </button>
            </li>
            <li>
              <button
                className={`nav-link ${activeTab === 'products' ? 'active' : ''}`}
                onClick={() => setActiveTab('products')}
              >
                Collection
              </button>
            </li>
            <li>
              <button
                className={`nav-link ${activeTab === 'analytics' ? 'active' : ''}`}
                onClick={() => setActiveTab('analytics')}
              >
                Metrics
              </button>
            </li>
            <li>
              <button
                className={`nav-link ${activeTab === 'contact' ? 'active' : ''}`}
                onClick={() => setActiveTab('contact')}
              >
                Contact
              </button>
            </li>
            <li>
              <button className="cart-trigger" onClick={openCart}>
                🛒 Cart ({cartCount})
              </button>
            </li>
          </ul>
        </nav>
      </div>
    </header>
  );
};
